int main(int argc, const char **argv)
{
    vcardcomponent *card;
    const char *file;

    if (argc != 2) {
        file = TEST_DATADIR "/test.vcf";
    } else {
        file = argv[1];
    }

    if (!test_parse_file(file)) {
        return 1;
    }
    card = test_comp_vanew();
    if (!card) {
        return 1;
    }
    test_add_props(card);
    test_n_restriction(card);
    test_v3_to_v4(card);
    test_ignore_backslash_at_eol();

    vcardcomponent_free(card);

    return 0;
}
